<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm('maintenance'); $pdo=pdo(); $rows=$pdo->query("SELECT *, (kilometrage_actuel-km_derniere_vidange) km_vidange, (kilometrage_actuel-km_derniere_courroie) km_courroie FROM voitures ORDER BY date_prochain_controle ASC")->fetchAll(); render_header('Maintenance'); ?><section class="panel"><h2>Suivi entretien, contrôle et assurance</h2><table><thead><tr><th>Véhicule</th><th>Vidange</th><th>Courroie</th><th>Contrôle technique</th><th>Assurance</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $v):?><tr><td><b><?=e($v['marque'].' '.$v['modele'])?></b><small><?=e($v['immatriculation'])?></small></td><td><?=e($v['km_vidange'])?> / <?=e($v['cadence_vidange'])?> km</td><td><?=e($v['km_courroie'])?> / <?=e($v['cadence_courroie'])?> km</td><td><?=e($v['date_prochain_controle'])?></td><td><?=e($v['assurance_expire_le'])?></td><td><span class="badge"><?=e($v['statut'])?></span></td></tr><?php endforeach;?></tbody></table></section><?php render_footer(); ?>
